from __future__ import annotations

from decimal import Decimal

import pytest
from app.libs.client_portal.schemas import PortfolioDTO
from app.libs.client_portal.service import ClientPortalService

from tests.libs.client_portal.conftest import (
    make_client,
    make_model,
    make_portfolio,
    make_subscription,
)

# --- Positive: derivations match hand-computed values ------------------------------


def test_portfolio_derives_totals_and_change_pct_for_two_positions(session):
    client_user = make_client(session, name="Cathy Client")
    model_a = make_model(session, name="Zeta Model", model_size=Decimal("1000000"))
    model_b = make_model(session, name="Alpha Model", model_size=Decimal("500000"))
    make_subscription(session, client_user, model_a, multiplier=Decimal("2"))
    make_subscription(session, client_user, model_b, multiplier=Decimal("1"))
    make_portfolio(
        session,
        client_user,
        cash_deposit=Decimal("100000"),
        amount_in_trade=Decimal("2500000"),
        previous_amount_in_trade=Decimal("2000000"),
    )

    svc = ClientPortalService(session)
    dto = svc.portfolio(client_user.id)

    assert isinstance(dto, PortfolioDTO)
    assert dto.cash_deposit == 100000.0
    assert dto.amount_in_trade == 2500000.0
    assert dto.total_value == 2600000.0
    assert dto.change_amount == 500000.0
    assert dto.change_pct == 0.25
    # name-sorted: "Alpha Model" before "Zeta Model"
    assert [p.model_name for p in dto.positions] == ["Alpha Model", "Zeta Model"]
    alpha = next(p for p in dto.positions if p.model_name == "Alpha Model")
    assert alpha.amount == 500000.0  # 1 * 500_000
    zeta = next(p for p in dto.positions if p.model_name == "Zeta Model")
    assert zeta.amount == 2000000.0  # 2 * 1_000_000


# --- Negative: missing client_portfolios row never 404s (DB B-3) ------------------


def test_portfolio_with_no_client_portfolios_row_returns_all_zero_no_exception(session):
    client_user = make_client(session, name="Pre014 Client")
    make_model(session, name="Solo Model")  # unsubscribed -- irrelevant to this client

    svc = ClientPortalService(session)
    dto = svc.portfolio(client_user.id)

    assert dto.cash_deposit == 0.0
    assert dto.amount_in_trade == 0.0
    assert dto.previous_amount_in_trade == 0.0
    assert dto.total_value == 0.0
    assert dto.change_pct is None
    assert dto.updated_at is None
    assert dto.positions == []


