def test_change_pct_is_none_when_previous_amount_is_zero_regardless_of_current(session):
    client_user = make_client(session, name="Cathy Client")
    make_portfolio(
        session,
        client_user,
        cash_deposit=Decimal("0"),
        amount_in_trade=Decimal("999999"),
        previous_amount_in_trade=Decimal("0"),
    )

    svc = ClientPortalService(session)
    dto = svc.portfolio(client_user.id)

    assert dto.change_pct is None
    assert dto.change_amount == 999999.0


def test_position_model_limit_is_raw_column_value_never_derived(session):
    client_user = make_client(session, name="Cathy Client")
    capped_model = make_model(session, name="Capped Model", model_limit=Decimal("5000000"))
    uncapped_model = make_model(session, name="Uncapped Model", model_limit=None)
    make_subscription(session, client_user, capped_model, multiplier=Decimal("1"))
    make_subscription(session, client_user, uncapped_model, multiplier=Decimal("1"))

    svc = ClientPortalService(session)
    dto = svc.portfolio(client_user.id)

    capped = next(p for p in dto.positions if p.model_name == "Capped Model")
    uncapped = next(p for p in dto.positions if p.model_name == "Uncapped Model")
    assert capped.model_limit == 5000000.0
    assert uncapped.model_limit is None


def test_position_reports_the_per_client_per_model_ib_account(session):
    """The account lives in client_ib_accounts keyed by (user_id, model_id) --
    client_profiles.ib_account is gone, so it is no longer shared across a
    client's models."""
    client_user = make_client(session, name="Cathy Client")
    model = make_model(session, name="Alpha Model")
    make_subscription(session, client_user, model)
    from app.models.pc import ClientIbAccount

    session.add(
        ClientIbAccount(user_id=client_user.id, model_id=model.id, ib_account="IB-777")
    )
    session.commit()

    svc = ClientPortalService(session)
    dto = svc.portfolio(client_user.id)

    assert dto.positions[0].client_ib == "IB-777"


def test_positions_exclude_a_fully_redeemed_zero_unit_subscription(session):
    """A full redemption floors the subscription's multiplier at 0 rather than
    deleting the row (its client_ib_accounts binding is permanent); the 0-unit
    row must not surface as a phantom position with 0 units/amount."""
    client_user = make_client(session, name="Cathy Client")
    held_model = make_model(session, name="Held Model")
    redeemed_model = make_model(session, name="Redeemed Model")
    make_subscription(session, client_user, held_model, multiplier=Decimal("1"))
    make_subscription(session, client_user, redeemed_model, multiplier=Decimal("0"))

    svc = ClientPortalService(session)
    dto = svc.portfolio(client_user.id)

    names = {p.model_name for p in dto.positions}
    assert "Held Model" in names
    assert "Redeemed Model" not in names


